'use strict';
/* ============ Orbit HR — pages & actions ============ */
const ACT = {}, CHG = {}, INP = {}, TABX = { pay: {}, perf: {}, att: {} };
const head = (t, sub, btns = '') => `<div class="page-head"><div><h1>${t}</h1>${sub ? `<p>${sub}</p>` : ''}</div><div class="right row wrap">${btns}</div></div>`;
const tabsBar = (key, items, def) => { const cur = S.tab[key] || def; return `<div class="tabs">${items.map(([k, l]) => `<button class="${cur === k ? 'on' : ''}" data-act="tab" data-k="${key}" data-v="${k}">${l}</button>`).join('')}</div>`; };
const tabOf = (key, def) => S.tab[key] || def;
const statusBadge = s => `<span class="badge ${{ Approved: 'ok', Paid: 'ok', Resolved: 'ok', Active: 'ok', Pending: 'warn', Open: 'warn', Onboarding: 'info', 'In progress': 'info', 'Notice period': 'warn', Rejected: 'bad', Exited: 'bad', Processed: 'info', Cancelled: 'bad', Booked: 'info', Registered: 'ok', Scheduled: 'info', Done: 'ok', 'No-show': 'bad', Confirmed: 'ok', Declined: 'bad', Requested: 'warn', Investigating: 'info', Executed: 'ok', Inactive: '' }[s] || ''}">${esc(s)}</span>`;
const stars = n => '★'.repeat(n) + '<span style="opacity:.25">' + '★'.repeat(5 - n) + '</span>';
const scope = () => can('scope.all') ? activeEmps() : [me(), ...reportsOf(me().id)];
function nextOcc(mmdd) { const T = TODAY(); let d = T.slice(0, 4) + '-' + mmdd; if (d < T) d = (+T.slice(0, 4) + 1) + '-' + mmdd; return d; }

/* ---------- global actions ---------- */
ACT.nav = () => $('#side')?.classList.remove('open');
ACT.menu = () => $('#side').classList.toggle('open');
ACT.logout = () => logout();
ACT.theme = () => { const t = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = t; localStorage.setItem('orbit_theme', t); };
ACT.togglepw = el => { const i = $('#pw'); i.type = i.type === 'password' ? 'text' : 'password'; el.textContent = i.type === 'password' ? 'Show' : 'Hide'; };
ACT.forgot = () => modal('Reset password', `<p class="muted" style="margin-top:0">Enter your work email and we'll send a reset link.</p>${fld('Work email', 'email', '', 'email', 'required')}<p class="small muted">Password resets are done by HR or your administrator — contact them if you cannot sign in.</p>`, d => { toast('If that account exists, a reset link is on its way.'); }, 'Send link');
ACT.tab = el => { S.tab[el.dataset.k] = el.dataset.v; render(); };
ACT.notes = el => {
  const box = $('#notemenu'); if (box.innerHTML) { box.innerHTML = ''; return; }
  const ns = DB.notes.filter(n => n.to === me().id).slice(0, 12);
  box.innerHTML = `<div class="pop-menu"><div class="row between" style="padding:8px 12px"><b>Notifications</b><a href="#" data-act="readall" class="small">Mark all read</a></div>${ns.map(n => `<div class="it ${n.read ? '' : 'unread'}">${esc(n.msg)}<div class="muted small">${new Date(n.ts).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</div></div>`).join('') || '<div class="empty">You\'re all caught up 🎉</div>'}</div>`;
};
ACT.readall = () => { DB.notes.forEach(n => { if (n.to === me().id) n.read = true; }); save(); render(); };
document.addEventListener('click', e => { if (!e.target.closest('#notemenu,[data-act=notes]')) { const b = $('#notemenu'); if (b) b.innerHTML = ''; } });

/* ---------- dispatch ---------- */
document.addEventListener('click', e => {
  const el = e.target.closest('[data-act]'); if (!el) return; const f = ACT[el.dataset.act]; if (!f) return;
  if (el.tagName === 'A' && el.dataset.act !== 'nav') e.preventDefault(); f(el, e);
});
document.addEventListener('change', e => { const el = e.target.closest('[data-chg]'); if (el && CHG[el.dataset.chg]) CHG[el.dataset.chg](el); });
document.addEventListener('input', e => { const el = e.target.closest('[data-inp]'); if (el && INP[el.dataset.inp]) INP[el.dataset.inp](el); });
document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k' && SESSION) { e.preventDefault(); ACT.palette(); } if (e.key === 'Escape') { $('.modal-bg')?.remove(); } });

/* ================= DASHBOARD ================= */
PAGE_FN.dashboard = () => {
  const u = me(), T = TODAY(), h = new Date().getHours(), greet = h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
  const act = activeEmps(); const st = act.map(e => dayStatus(e.id, T).s);
  const present = st.filter(s => ['present', 'late', 'wfh'].includes(s)).length, onLeave = st.filter(s => s === 'leave').length;
  const mine = dayStatus(u.id, T), mgrView = isHR() || isMgr(), pc = pendingCount();
  const openPos = sum(DB.jobs.filter(j => j.status === 'Open'), j => j.openings);
  const myGoals = DB.goals.filter(g => g.emp === u.id), gAvg = myGoals.length ? Math.round(sum(myGoals, g => g.progress) / myGoals.length) : 0;
  const lastDay = (() => { const d = new Date(); return iso(new Date(d.getFullYear(), d.getMonth() + 1, 0)); })();
  const kpis = mgrView ? [[act.length, 'Active headcount', `${DB.employees.filter(e => e.status === 'Onboarding').length} onboarding`], [present, 'Present today', `${Math.round(present / Math.max(1, act.length) * 100)}% of workforce`], [onLeave, 'On leave today', 'approved'], [isHR() ? openPos : pc, isHR() ? 'Open positions' : 'Pending approvals', isHR() ? `${DB.cands.length} candidates in pipeline` : 'need your action']]
    : [[leaveBalance(u.id, 'CL').left, 'Casual leave left', `of ${DB.settings.quota.CL} this year`], [leaveBalance(u.id, 'EL').left, 'Earned leave left', `of ${DB.settings.quota.EL} this year`], [gAvg + '%', 'Goal progress', `${myGoals.length} active goals`], [fmtShort(lastDay), 'Next payday', 'salary credited']];
  const punch = mine.s === 'notin' ? `<div class="row wrap">${siteSelect()}<button class="btn primary" data-act="checkin">${ic('clock')} Check in</button></div>`
    : mine.working ? `<div class="row wrap"><span class="badge ok">Checked in ${mine.r.in} · ${mine.r.mode}</span><button class="btn" data-act="checkout">Check out</button></div>`
      : mine.r ? `<span class="badge acc">Done · ${mine.r.in}–${mine.r.out} (${(mine.h || 0).toFixed(1)}h)</span>` : `<span class="badge">${STATUS_LABEL[mine.s] || ''}${mine.lv ? ' — ' + LEAVE_TYPES[mine.lv.type] : ''}${mine.h ? '' : ''}</span>`;
  // events
  const ev = []; act.forEach(e => { const b = nextOcc(e.dob.slice(5)); ev.push([b, '🎂', `${e.name}'s birthday`]); const a = nextOcc(e.joined.slice(5)), y = +a.slice(0, 4) - +e.joined.slice(0, 4); if (y >= 1) ev.push([a, '🏅', `${e.name} — ${y} yr${y > 1 ? 's' : ''} at Orbit`]); });
  HOLIDAYS.forEach(h => { if (h[0] >= T) ev.push([h[0], '🎉', h[1]]); }); ev.sort((a, b) => a[0] < b[0] ? -1 : 1);
  const off = act.filter(e => dayStatus(e.id, T).s === 'leave');
  const trend = []; for (let k = 13; k >= 1; k--) { const d = addDays(T, -k); const base = act.filter(e => !['weekend', 'holiday', 'na'].includes(dayStatus(e.id, d).s)); if (!base.length) continue; const p = base.filter(e => ['present', 'late', 'wfh'].includes(dayStatus(e.id, d).s)).length; trend.push({ l: fmtShort(d), v: Math.round(p / base.length * 100) }); }
  const depts = DEPTS.map((d, i) => ({ l: d, v: act.filter(e => e.dept === d).length, c: COLORS[i] })).filter(d => d.v);
  return `${head(`${greet}, ${esc(u.name.split(' ')[0])} 👋`, new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }), isHR() ? `<button class="btn" data-act="news_new">${ic('mega')} Post announcement</button><button class="btn primary" data-act="emp_new">${ic('plus')} Add employee</button>` : `<button class="btn primary" data-act="leave_new">${ic('plus')} Apply leave</button>`)}
  <div class="grid g4" style="margin-bottom:16px">${kpis.map(k => `<div class="card kpi"><span class="v">${k[0]}</span><span class="l">${k[1]}</span><span class="d muted">${k[2]}</span></div>`).join('')}</div>
  <div class="grid g-main"><div class="col" style="gap:16px">
   <div class="card"><div class="row between wrap"><div><div class="muted small">Your day</div><div class="clock" id="clk">${new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div></div>${punch}</div></div>
   ${pc ? `<div class="card pad0"><div style="padding:16px 18px 0"><h3>Needs your approval <span class="badge warn">${pc}</span></h3></div>${approvalsTable()}</div>` : ''}
   ${mgrView ? `<div class="grid g2"><div class="card"><header><h3>Attendance trend</h3><span class="muted small">% present, last 2 weeks</span></header>${lineChart(trend, { fmt: x => x + '%' })}</div><div class="card"><header><h3>Headcount by department</h3></header>${donut(depts, 130)}</div></div>` : ''}
   <div class="card"><header><h3>Announcements</h3></header><div class="list">${DB.news.slice().sort((a, b) => (b.pin ? 1 : 0) - (a.pin ? 1 : 0)).slice(0, 4).map(n => `<div><div class="row"><b>${n.pin ? '📌 ' : ''}${esc(n.title)}</b><span class="muted small right">${fmtShort(n.ts)}</span></div><div class="muted">${esc(n.body)}</div><div class="small muted">— ${esc(emp(n.by)?.name)}</div></div>`).join('')}</div></div>
  </div><div class="col" style="gap:16px">
   <div class="card"><header><h3>Out today</h3><span class="badge vio">${off.length}</span></header>${off.length ? off.map(e => `<div class="row" style="padding:5px 0">${avatar(e, 'sm')}<span>${esc(e.name)}</span><span class="muted small right">${LEAVE_TYPES[dayStatus(e.id, T).lv.type]}</span></div>`).join('') : '<div class="muted">Everyone is in 🎯</div>'}</div>
   <div class="card"><header><h3>Coming up</h3></header><div class="list">${ev.slice(0, 7).map(x => `<div class="row"><span style="font-size:18px">${x[1]}</span><div style="flex:1">${esc(x[2])}</div><span class="muted small">${x[0] === T ? 'Today' : fmtShort(x[0])}</span></div>`).join('')}</div></div>
   <div class="card"><header><h3>Recent kudos</h3><a href="#" data-act="tabgo" data-p="performance" data-k="perf" data-v="kudos" class="small">All</a></header><div class="list">${DB.kudos.slice(0, 3).map(k => `<div><div class="small"><b>${esc(emp(k.from)?.name.split(' ')[0])}</b> → <b>${esc(emp(k.to)?.name.split(' ')[0])}</b> <span class="badge vio">${esc(k.badge)}</span></div><div class="muted">${esc(k.msg)}</div></div>`).join('')}</div></div>
  </div></div>`;
};
ACT.tabgo = el => { S.tab[el.dataset.k] = el.dataset.v; location.hash = '#/' + el.dataset.p; };
ACT.checkin = () => { const T = TODAY(); DB.att[me().id] ||= {}; DB.att[me().id][T] = { in: nowHM(), out: null, mode: punchWhere().mode, site: punchWhere().site }; save(); render(); toast('Checked in at ' + nowHM() + '. Have a great day!'); };
ACT.checkout = () => { const r = DB.att[me().id][TODAY()]; r.out = nowHM(); if (hm2m(r.out) <= hm2m(r.in)) r.out = r.in; save(); render(); toast('Checked out. See you tomorrow!'); };
ACT.news_new = () => modal('Post announcement', `<div class="col">${fld('Title', 'title', '', 'text', 'required')}<label class="f">Message<textarea class="input" name="body" rows="4" required></textarea></label><label class="row small"><input type="checkbox" name="pin"> Pin to top</label></div>`, d => { DB.news.unshift({ id: uid('N'), title: d.title, body: d.body, by: me().id, ts: TODAY(), pin: !!d.pin }); activeEmps().forEach(e => e.id !== me().id && notify(e.id, '📢 ' + d.title)); log('Posted announcement: ' + d.title); save(); render(); toast('Announcement posted'); }, 'Publish');

/* approvals (shared) */
function approvalsTable() {
  const rows = [];
  DB.leaves.filter(canApproveLeave).forEach(l => rows.push([emp(l.emp), `${LEAVE_TYPES[l.type]} · ${l.days}d`, `${fmtShort(l.from)}${l.to !== l.from ? ' – ' + fmtShort(l.to) : ''} — ${esc(l.reason)}`, 'lv', l.id]));
  DB.regs.filter(canApproveReg).forEach(r => rows.push([emp(r.emp), 'Attendance fix', `${fmtShort(r.date)} ${r.in}–${r.out} — ${esc(r.reason)}`, 'reg', r.id]));
  DB.claims.filter(canApproveClaim).forEach(c => rows.push([emp(c.emp), `Expense · ${inr(c.amount)}`, `${esc(c.cat)} — ${esc(c.desc)}`, 'claim', c.id]));
  if (!rows.length) return '<div class="empty">Nothing waiting on you 🎉</div>';
  return `<div class="tablewrap"><table><tbody>${rows.map(r => `<tr><td>${person(r[0])}</td><td><b>${r[1]}</b><div class="muted small">${r[2]}</div></td><td class="nowrap" style="text-align:right"><button class="btn sm primary" data-act="appr" data-t="${r[3]}" data-id="${r[4]}" data-v="Approved">Approve</button> <button class="btn sm danger" data-act="appr" data-t="${r[3]}" data-id="${r[4]}" data-v="Rejected">Reject</button></td></tr>`).join('')}</tbody></table></div>`;
}
ACT.appr = el => {
  const { t, id, v } = el.dataset; const col = { lv: DB.leaves, reg: DB.regs, claim: DB.claims }[t]; const x = col.find(i => i.id === id); x.status = v; x.by = me().id;
  if (t === 'reg' && v === 'Approved') { DB.att[x.emp] ||= {}; DB.att[x.emp][x.date] = { in: x.in, out: x.out, mode: 'Office' }; }
  notify(x.emp, `${t === 'lv' ? 'Your leave' : t === 'reg' ? 'Your attendance fix' : 'Your expense claim'} was ${v.toLowerCase()} by ${me().name}`); log(`${v} ${t} for ${emp(x.emp).name}`); save(); render(); toast(v);
};

/* ================= PEOPLE ================= */
PAGE_FN.employees = arg => arg ? profile(arg) : directory();
function directory() {
  const f = S.emp; let list = DB.employees.filter(e => (!f.status || (f.status === 'Active' ? e.status !== 'Exited' : e.status === f.status)) && (!f.dept || e.dept === f.dept) && (!S.branch || branchOf(e) === S.branch) && (!f.mgr || e.mgr === f.mgr) && (!f.role || e.role === f.role) && (!f.q || (e.name + e.title + e.email + e.dept + e.skills.join(' ')).toLowerCase().includes(f.q.toLowerCase())));
  const SORTS = { name: (a, b) => a.name.localeCompare(b.name), new: (a, b) => (b.joined || '').localeCompare(a.joined || ''), old: (a, b) => (a.joined || '').localeCompare(b.joined || ''), dept: (a, b) => a.dept.localeCompare(b.dept) || a.name.localeCompare(b.name) }; if (SORTS[f.sort]) list = [...list].sort(SORTS[f.sort]);
  const cards = list.map(e => `<a href="#/employees/${e.id}" class="card" style="color:inherit;display:block"><div class="row">${avatar(e, 'lg')}<div style="min-width:0"><div style="font-weight:700;font-size:15px">${esc(e.name)}</div><div class="muted small">${esc(e.title)}</div><div class="row wrap" style="gap:4px;margin-top:6px"><span class="badge">${esc(e.dept)}</span>${e.status !== 'Active' ? statusBadge(e.status) : ''}</div></div></div><div class="muted small" style="margin-top:12px">📍 ${esc(e.loc)} · ✉ ${esc(e.email)}</div></a>`).join('');
  const table = `<div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Department</th><th>Manager</th><th>Location</th><th>Joined</th><th>Status</th></tr></thead><tbody>${list.map(e => `<tr class="click" onclick="location.hash='#/employees/${e.id}'"><td>${person(e)}</td><td>${esc(e.dept)}</td><td>${esc(emp(e.mgr)?.name || '—')}</td><td>${esc(e.loc)}</td><td>${fmtDate(e.joined)}</td><td>${statusBadge(e.status)}</td></tr>`).join('')}</tbody></table></div>`;
  return `${head('People', `${list.length} ${list.length === 1 ? 'person' : 'people'} · company directory`, `${isHR() ? `<button class="btn" data-act="emp_csv">${ic('download')} Export CSV</button><button class="btn primary" data-act="emp_new">${ic('plus')} Add employee</button>` : ''}`)}
  <div class="toolbar"><input class="input" id="eq" data-inp="empq" placeholder="Search name, role, skill…" value="${esc(f.q)}" style="min-width:260px"><select class="select" data-chg="empdept"><option value="">All departments</option>${DEPTS.map(d => `<option ${f.dept === d ? 'selected' : ''}>${d}</option>`).join('')}</select>
  <select class="select" data-chg="branch" title="Location"><option value="">All locations</option>${rows('branches').map(b => `<option value="${b.id}" ${S.branch === b.id ? 'selected' : ''}>${esc(b.name.replace(/ — .*$/, ''))}${b.type === 'site' ? ' (site)' : ''}</option>`).join('')}</select><select class="select" data-chg="empmgr" title="Reporting manager"><option value="">Any manager</option>${[...new Set(DB.employees.map(e => e.mgr).filter(Boolean))].map(id => emp(id)).filter(Boolean).sort((a, b) => a.name.localeCompare(b.name)).map(m => `<option value="${m.id}" ${f.mgr === m.id ? 'selected' : ''}>Team of ${esc(m.name)}</option>`).join('')}</select><select class="select" data-chg="emprole" title="Access level"><option value="">All access levels</option>${[['admin', 'Admin'], ['hr', 'HR'], ['manager', 'Manager'], ['employee', 'Employee']].map(r => `<option value="${r[0]}" ${f.role === r[0] ? 'selected' : ''}>${r[1]}</option>`).join('')}</select>
  <select class="select" data-chg="empstatus">${['Active', 'Onboarding', 'Notice period', 'Exited', ''].map(s => `<option value="${s}" ${f.status === s ? 'selected' : ''}>${s || 'Any status'}</option>`).join('')}</select>
  <select class="select" data-chg="empsort" title="Sort">${[['', 'Sort: default'], ['name', 'Name A–Z'], ['new', 'Newest joined'], ['old', 'Longest serving'], ['dept', 'Department']].map(o => `<option value="${o[0]}" ${(f.sort || '') === o[0] ? 'selected' : ''}>${o[1]}</option>`).join('')}</select>${(f.q || f.dept || f.mgr || f.role || f.sort || S.branch || f.status !== 'Active') ? '<button class="btn sm ghost" data-act="empclear">✕ Clear</button>' : ''}<span class="muted small">${list.length} shown</span>
  <div class="pill-toggle right"><button class="${f.view === 'cards' ? 'on' : ''}" data-act="empview" data-v="cards">Cards</button><button class="${f.view === 'table' ? 'on' : ''}" data-act="empview" data-v="table">Table</button></div></div>
  ${list.length ? (f.view === 'cards' ? `<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(290px,1fr))">${cards}</div>` : table) : '<div class="card empty">No one matches those filters.</div>'}`;
}
INP.empq = el => { S.emp.q = el.value; render(); }; CHG.empdept = el => { S.emp.dept = el.value; render(); }; CHG.empstatus = el => { S.emp.status = el.value; render(); };
ACT.empview = el => { S.emp.view = el.dataset.v; render(); };
ACT.emp_csv = () => download('employees.csv', csv([['ID', 'Name', 'Email', 'Title', 'Department', 'Manager', 'Location', 'Joined', 'Status'], ...DB.employees.map(e => [e.id, e.name, e.email, e.title, e.dept, emp(e.mgr)?.name || '', e.loc, e.joined, e.status])]));
function empForm(e = {}) {
  const mgrs = DB.employees.filter(x => x.status !== 'Exited' && x.id !== e.id).map(x => [x.id, x.name + ' — ' + x.title]);
  return `<div class="form-grid">${fld('Full name', 'name', e.name, 'text', 'required')}${fld('Work email', 'email', e.email, 'email', 'required')}${fld('Job title', 'title', e.title, 'text', 'required')}${sel('Department', 'dept', DEPTS, e.dept)}
  ${sel('Reports to', 'mgr', [['', '— none —'], ...mgrs], e.mgr || '')}${sel('Access role', 'role', [['employee', 'Employee'], ['manager', 'Manager'], ['hr', 'HR'], ['admin', 'Admin']], e.role || 'employee')}
  ${fld('Annual CTC (₹)', 'salary', e.salary || 600000, 'number', 'min="0" required')}${fld('Joining date', 'joined', e.joined || TODAY(), 'date', 'required')}${sel('Branch', 'branch', rows('branches').map(b => [b.id, b.name]), e.branch || 'B1')}${fld('Phone', 'phone', e.phone)}${fld('Location', 'loc', e.loc || '')}
  ${sel('Gender', 'gender', [['F', 'Female'], ['M', 'Male'], ['O', 'Other']], e.gender || 'F')}${fld('Date of birth', 'dob', e.dob || '1995-01-01', 'date')}</div>`;
}
ACT.emp_new = () => modal('Add employee', empForm(), d => {
  if (DB.employees.some(x => x.email.toLowerCase() === d.email.toLowerCase())) { toast('That email is already in use', 'err'); return false; }
  const id = 'E' + String(DB.employees.length + 1).padStart(3, '0'); const e = { id, ...d, mgr: d.mgr || null, salary: +d.salary, pass: tempPassFor(id), status: 'Onboarding', skills: [], color: COLORS[DB.employees.length % COLORS.length], emergency: '', exit: null };
  DB.employees.push(e); DB.att[id] = {}; ONB_TASKS.forEach(t => DB.tasks.push({ id: uid('O'), emp: id, title: t[0], owner: t[1], done: false })); notify(id, 'Welcome to Orbit! Start with your onboarding checklist.'); log('Added employee ' + e.name); save(); toast(e.name + ' added — onboarding checklist created'); location.hash = '#/employees/' + id;
}, 'Add employee', true);
ACT.emp_edit = el => { const e = emp(el.dataset.id); modal('Edit ' + esc(e.name), empForm(e), d => { const oldCtc = e.salary; Object.assign(e, d, { mgr: d.mgr || null, salary: oldCtc }); if (+d.salary !== +oldCtc) reviseSalary(e, { ctc: +d.salary, from: ymOf(TODAY()) + '-01', reason: 'Edited in employee profile' }); log('Edited ' + e.name); save(); render(); toast('Saved'); }, 'Save changes', true); };
ACT.emp_exit = el => { const e = emp(el.dataset.id); modal('Start exit for ' + esc(e.name), `<div class="col">${fld('Last working day', 'exit', addDays(TODAY(), 30), 'date', 'required')}${sel('Reason', 'why', ['Resignation', 'Better opportunity', 'Relocation', 'Higher studies', 'Termination', 'Retirement'])}<p class="small muted">An offboarding checklist will be created and attendance/payroll stop after the last day.</p></div>`, d => { e.status = 'Notice period'; e.exit = d.exit; ['Knowledge transfer plan', 'Return laptop & access card', 'Exit interview', 'Full & final settlement', 'Revoke system access'].forEach((t, i) => DB.tasks.push({ id: uid('O'), emp: e.id, title: t, owner: i === 0 ? 'Employee' : i === 4 ? 'IT' : 'HR', done: false, off: true })); log('Started exit for ' + e.name); save(); render(); toast('Offboarding started'); }, 'Start exit'); };
ACT.emp_finish = el => confirmBox('Mark this employee as exited? They will no longer be able to sign in.', () => { const e = emp(el.dataset.id); e.status = 'Exited'; log('Completed exit for ' + e.name); save(); render(); });
ACT.emp_react = el => { const e = emp(el.dataset.id); e.status = 'Active'; e.exit = null; log('Reactivated ' + e.name); save(); render(); };
ACT.emp_pw = el => { const e = emp(el.dataset.id); e.pass = tempPassFor(e.id); log('Reset password for ' + e.name); save(); };
function profile(id) {
  const e = emp(id); if (!e) return '<div class="card empty">Employee not found.</div>';
  const own = e.id === me().id, canPay = can('salary.read') || own, tab = tabOf('prof', 'ov'); const m = emp(e.mgr), rep = reportsOf(e.id);
  const tabs = [['ov', 'Overview'], ['time', 'Time off'], ['perf', 'Performance']]; if (canPay) tabs.splice(1, 0, ['job', 'Job & pay']);
  let body = '';
  if (tab === 'ov') body = `<div class="grid g2"><div class="card"><header><h3>Contact</h3></header><div class="list"><div>✉ ${esc(e.email)}</div><div>📞 ${esc(e.phone)}</div><div>📍 ${esc(e.loc)}</div>${canPay ? `<div class="muted">🚑 ${esc(e.emergency || 'Not provided')}</div>` : ''}</div></div>
    <div class="card"><header><h3>Work</h3></header><div class="list"><div>Reports to: ${m ? `<a href="#/employees/${m.id}">${esc(m.name)}</a>` : '—'}</div><div>Joined: ${fmtDate(e.joined)}</div>${e.exit ? `<div>Last day: <b>${fmtDate(e.exit)}</b></div>` : ''}<div>Tenure: ${(daysBetween(e.joined, TODAY()) / 365).toFixed(1)} years</div></div></div>
    <div class="card"><header><h3>Skills</h3></header><div class="row wrap">${e.skills.map(s => `<span class="badge acc">${esc(s)}</span>`).join('') || '<span class="muted">None added</span>'}</div></div>
    <div class="card"><header><h3>Direct reports (${rep.length})</h3></header>${rep.map(r => `<a href="#/employees/${r.id}" class="row" style="padding:5px 0;color:inherit">${avatar(r, 'sm')}${esc(r.name)}<span class="muted small right">${esc(r.title)}</span></a>`).join('') || '<span class="muted">No direct reports</span>'}</div></div>`;
  if (tab === 'job') { const ps = payslip(e.id, ymOf(TODAY())); body = `<div class="grid g2"><div class="card"><header><h3>Compensation</h3></header><div class="kpi"><span class="v">${inr(e.salary)}</span><span class="l">Annual CTC</span></div>
    <table style="margin-top:12px"><tbody>${ps.earn.filter(x => x[0] !== 'Reimbursements').map(x => `<tr><td>${x[0]}</td><td style="text-align:right">${inr(x[1])}/mo</td></tr>`).join('')}<tr><td><b>Gross monthly</b></td><td style="text-align:right"><b>${inr(ps.gross)}</b></td></tr></tbody></table></div>
    <div class="card"><header><h3>Employer details</h3></header><div class="list"><div>Employee ID: <b>${e.id}</b></div><div>Role: <b>${esc(e.title)}</b></div><div>Department: <b>${esc(e.dept)}</b></div><div>Access level: <b>${e.role}</b></div><div>Est. annual tax (new regime): <b>${inr(taxAnnual(e.salary))}</b></div></div></div></div>`; }
  if (tab === 'time') { body = `<div class="grid g3">${['CL', 'SL', 'EL'].map(t => { const b = leaveBalance(e.id, t); return `<div class="card kpi"><span class="v">${b.left}</span><span class="l">${LEAVE_TYPES[t]} left</span><span class="d muted">${b.used} used · ${b.pending} pending</span></div>`; }).join('')}</div>
    <div class="card pad0" style="margin-top:16px"><table><thead><tr><th>Type</th><th>Dates</th><th>Days</th><th>Status</th></tr></thead><tbody>${DB.leaves.filter(l => l.emp === e.id).map(l => `<tr><td>${LEAVE_TYPES[l.type]}</td><td>${fmtShort(l.from)} – ${fmtShort(l.to)}</td><td>${l.days}</td><td>${statusBadge(l.status)}</td></tr>`).join('') || '<tr><td colspan="4" class="empty">No leave history</td></tr>'}</tbody></table></div>`; }
  if (tab === 'perf') { const gs = DB.goals.filter(g => g.emp === e.id), rv = DB.reviews.find(r => r.emp === e.id); body = `<div class="grid g2"><div class="card"><header><h3>Goals</h3></header>${gs.map(g => `<div style="margin-bottom:12px"><div class="row between"><span>${esc(g.title)}</span><b>${g.progress}%</b></div><div class="progress"><i style="width:${g.progress}%"></i></div></div>`).join('') || '<div class="muted">No goals set</div>'}</div>
    <div class="card"><header><h3>Review · H2 2026</h3></header>${rv ? `<div class="list"><div>Self: ${rv.self ? stars(rv.self) : '<span class="muted">pending</span>'}</div><div>Manager: ${rv.mgr ? stars(rv.mgr) : '<span class="muted">pending</span>'}</div></div>` : '<div class="muted">Not in this cycle</div>'}</div></div>`; }
  return `<div class="card" style="margin-bottom:16px"><div class="row wrap">${avatar(e, 'lg')}<div><h1>${esc(e.name)}</h1><div class="muted">${esc(e.title)} · ${esc(e.dept)} ${statusBadge(e.status)}</div></div><div class="right row wrap"><a class="btn" href="#/employees">← Back</a>${isHR() ? `<button class="btn" data-act="emp_edit" data-id="${e.id}">Edit</button><button class="btn" data-act="emp_pw" data-id="${e.id}">Reset password</button>${e.status === 'Notice period' ? `<button class="btn danger" data-act="emp_finish" data-id="${e.id}">Complete exit</button>` : e.status === 'Exited' ? `<button class="btn" data-act="emp_react" data-id="${e.id}">Reactivate</button>` : e.id !== me().id ? `<button class="btn danger" data-act="emp_exit" data-id="${e.id}">Start exit</button>` : ''}` : ''}</div></div></div>${tabsBar('prof', tabs, 'ov')}${body}`;
}

/* ================= ATTENDANCE ================= */
PAGE_FN.attendance = () => {
  const u = me(), tabs = [['my', 'Calendar']]; if (isHR() || isMgr()) tabs.push(['team', 'Team today']); if (isHR() || isMgr()) tabs.push(['tardy', 'Tardy records']); if (can('att.manual')) tabs.push(['manual', 'Manual attendance']); tabs.push(['secure', 'Secure check-in']); tabs.push(['reg', 'Regularization']); const tab = tabOf('att', 'my'); let body = TABX.att[tab] ? TABX.att[tab]() : '';
  if (tab === 'my') {
    const T = TODAY(), ym = S.calMonth || ymOf(T), target = S.calEmp || u.id, first = ym + '-01', last = addDays(addDays(first, 32).slice(0, 8) + '01', -1), pad = dow(first);
    const days = []; for (let d = first; d <= last; d = addDays(d, 1)) days.push(d); const sts = days.map(d => [d, dayStatus(target, d)]);
    const cnt = k => sts.filter(x => x[1].s === k).length, hrs = sts.filter(x => x[1].h).map(x => x[1].h), avg = hrs.length ? sum(hrs) / hrs.length : 0;
    const pm = addDays(first, -1).slice(0, 7), nm = addDays(last, 1).slice(0, 7);
    body = `<div class="toolbar"><button class="btn" data-act="calnav" data-v="${pm}">←</button><b style="min-width:140px;text-align:center">${monthName(ym)}</b><button class="btn" data-act="calnav" data-v="${nm}">→</button>
      ${(isHR() || isMgr()) ? `<select class="select right" data-chg="calemp">${scope().map(e => `<option value="${e.id}" ${e.id === target ? 'selected' : ''}>${esc(e.name)}</option>`).join('')}</select>` : ''}</div>
      <div class="grid g4" style="margin-bottom:16px">${[[cnt('present') + cnt('late'), 'Days present'], [cnt('late'), 'Late arrivals'], [cnt('wfh'), 'Work from home'], [avg.toFixed(1) + 'h', 'Avg hours / day']].map(k => `<div class="card kpi"><span class="v">${k[0]}</span><span class="l">${k[1]}</span></div>`).join('')}</div>
      <div class="card"><div class="cal">${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(x => `<div class="h">${x}</div>`).join('')}${'<div class="d x"></div>'.repeat(pad)}${sts.map(([d, s]) => `<div class="d ${s.s} ${d === T ? 'today' : ''}" title="${esc(s.h || '')}"><b>${+d.slice(8)}</b><small>${s.s === 'future' || s.s === 'na' ? '' : (s.s === 'holiday' ? esc(s.h) : s.r ? `${s.r.in}${s.r.out ? '–' + s.r.out : ''}` : STATUS_LABEL[s.s])}</small></div>`).join('')}</div>
      <div class="legend" style="margin-top:14px">${[['present', 'Present'], ['late', 'Late'], ['wfh', 'WFH'], ['half', 'Half day'], ['leave', 'Leave'], ['absent', 'Absent'], ['holiday', 'Holiday']].map(([k, l]) => `<span><i class="cal-${k}" style="background:var(--${{ present: 'green', late: 'amber', wfh: 'blue', half: 'amber', leave: 'violet', absent: 'red', holiday: 'accent' }[k]}-soft,var(--accent-soft))"></i>${l}</span>`).join('')}</div></div>`;
  }
  if (tab === 'team') {
    const T = TODAY(), rows = scope().filter(e => e.id !== u.id || isHR()).map(e => [e, dayStatus(e.id, T)]);
    body = `<div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Status</th><th>In</th><th>Out</th><th>Location</th></tr></thead><tbody>${rows.map(([e, s]) => `<tr><td>${person(e)}</td><td><span class="badge ${STATUS_BADGE[s.s] || ''}">${STATUS_LABEL[s.s]}</span></td><td>${s.r?.in || '—'}</td><td>${s.r?.out || (s.working ? '<span class="muted">working</span>' : '—')}</td><td class="small">${locLabel(s.r)}${s.r?.manual ? ' <span class="badge vio">manual</span>' : ''}</td></tr>`).join('')}</tbody></table></div><div style="margin-top:12px"><button class="btn" data-act="att_csv">${ic('download')} Export last 30 days (CSV)</button></div>`;
  }
  if (tab === 'reg') {
    const mineR = DB.regs.filter(r => r.emp === u.id || canApproveReg(r) || (isHR()));
    body = `<div class="row" style="margin-bottom:12px"><span class="muted">Forgot to punch? Request a correction for manager approval.</span><button class="btn primary right" data-act="reg_new">${ic('plus')} Request correction</button></div><div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Date</th><th>Times</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${mineR.map(r => `<tr><td>${person(emp(r.emp))}</td><td>${fmtDate(r.date)}</td><td>${r.in}–${r.out}</td><td>${esc(r.reason)}</td><td>${statusBadge(r.status)}</td><td>${canApproveReg(r) ? `<button class="btn sm primary" data-act="appr" data-t="reg" data-id="${r.id}" data-v="Approved">Approve</button> <button class="btn sm danger" data-act="appr" data-t="reg" data-id="${r.id}" data-v="Rejected">Reject</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No requests yet</td></tr>'}</tbody></table></div>`;
  }
  return head('Attendance', 'Track time, shifts and corrections') + tabsBar('att', tabs, 'my') + body;
};
ACT.calnav = el => { S.calMonth = el.dataset.v; render(); }; CHG.calemp = el => { S.calEmp = el.value; render(); };
ACT.att_csv = () => { const rows = [['Employee', 'Date', 'Status', 'In', 'Out', 'Hours']]; scope().forEach(e => { for (let k = 30; k >= 0; k--) { const d = addDays(TODAY(), -k), s = dayStatus(e.id, d); if (['weekend', 'future', 'na'].includes(s.s)) continue; rows.push([e.name, d, STATUS_LABEL[s.s], s.r?.in || '', s.r?.out || '', (s.h || 0).toFixed(1)]); } }); download('attendance.csv', csv(rows)); };
ACT.reg_new = () => modal('Attendance correction', `<div class="form-grid">${fld('Date', 'date', addDays(TODAY(), -1), 'date', `max="${TODAY()}" required`, 'full')}${fld('In time', 'in', '09:30', 'time', 'required')}${fld('Out time', 'out', '18:30', 'time', 'required')}<label class="f full">Reason<textarea class="input" name="reason" rows="2" required></textarea></label></div>`, d => {
  if (hm2m(d.out) <= hm2m(d.in)) { toast('Out time must be after in time', 'err'); return false; }
  DB.regs.unshift({ id: uid('R'), emp: me().id, ...d, status: 'Pending' }); const m = me().mgr || 'E002'; notify(m, `${me().name} requested an attendance correction`); save(); render(); toast('Request sent for approval');
}, 'Submit');

/* ================= LEAVE ================= */
PAGE_FN.leave = () => {
  const u = me(), pc = DB.leaves.filter(canApproveLeave).length, tabs = [['my', 'My leave'], ['appr', `Approvals${pc ? ' (' + pc + ')' : ''}`], ['team', 'Team calendar'], ['hol', 'Holidays']], tab = tabOf('leave', 'my'); let body = '';
  if (tab === 'my') {
    body = `<div class="grid g4" style="margin-bottom:16px">${['CL', 'SL', 'EL', 'CO'].map(t => { const b = leaveBalance(u.id, t); return `<div class="card kpi"><span class="v">${b.left}<small class="muted" style="font-size:14px"> / ${b.quota}</small></span><span class="l">${LEAVE_TYPES[t]}</span><div class="progress" style="margin-top:6px"><i style="width:${b.quota ? Math.round((b.used + b.pending) / b.quota * 100) : 0}%"></i></div></div>`; }).join('')}</div>
    <div class="card pad0 tablewrap"><table><thead><tr><th>Type</th><th>Dates</th><th>Days</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${DB.leaves.filter(l => l.emp === u.id).sort((a, b) => a.from < b.from ? 1 : -1).map(l => `<tr><td>${LEAVE_TYPES[l.type]}</td><td>${fmtShort(l.from)}${l.to !== l.from ? ' – ' + fmtShort(l.to) : ''}</td><td>${l.days}</td><td>${esc(l.reason)}</td><td>${statusBadge(l.status)}${l.by ? `<div class="muted small">by ${esc(emp(l.by)?.name.split(' ')[0])}</div>` : ''}</td><td>${l.status === 'Pending' || (l.status === 'Approved' && l.from > TODAY()) ? `<button class="btn sm danger" data-act="lv_cancel" data-id="${l.id}">Cancel</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No leave applied yet</td></tr>'}</tbody></table></div>`;
  }
  if (tab === 'appr') body = `<div class="card pad0">${approvalsTable()}</div>`;
  if (tab === 'team') { const T = TODAY(), end = addDays(T, 45), ls = DB.leaves.filter(l => l.status !== 'Rejected' && l.status !== 'Cancelled' && l.to >= T && l.from <= end && (isHR() || l.emp === u.id || emp(l.emp).mgr === u.id || emp(l.emp).dept === u.dept)).sort((a, b) => a.from < b.from ? -1 : 1); body = `<div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Days</th><th>Status</th></tr></thead><tbody>${ls.map(l => `<tr><td>${person(emp(l.emp))}</td><td>${LEAVE_TYPES[l.type]}</td><td>${fmtShort(l.from)}${l.to !== l.from ? ' – ' + fmtShort(l.to) : ''}</td><td>${l.days}</td><td>${statusBadge(l.status)}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No upcoming leave in the next 45 days</td></tr>'}</tbody></table></div>`; }
  if (tab === 'hol') body = `<div class="card pad0"><table><thead><tr><th>Date</th><th>Day</th><th>Holiday</th></tr></thead><tbody>${HOLIDAYS.map(h => `<tr><td>${fmtDate(h[0])}</td><td>${new Date(h[0] + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'long' })}</td><td>${h[0] < TODAY() ? '<span class="muted">' + h[1] + '</span>' : '<b>' + h[1] + '</b>'}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Default national holiday list — check it against your state’s official calendar.</p>`;
  return head('Leave', 'Balances, requests and approvals', `<button class="btn primary" data-act="leave_new">${ic('plus')} Apply leave</button>`) + tabsBar('leave', tabs, 'my') + body;
};
ACT.leave_new = () => {
  const m = modal('Apply for leave', `<div class="form-grid">${sel('Leave type', 'type', Object.entries(LEAVE_TYPES), 'CL', 'full')}${fld('From', 'from', TODAY(), 'date', 'required')}${fld('To', 'to', TODAY(), 'date', 'required')}<div class="full" id="lvinfo" class="muted small"></div><label class="f full">Reason<textarea class="input" name="reason" rows="2" required></textarea></label></div>`, d => {
    if (d.to < d.from) { toast('End date is before start date', 'err'); return false; } const days = leaveDays(d.from, d.to); if (!days) { toast('Selected dates are all weekends/holidays', 'err'); return false; }
    const b = leaveBalance(me().id, d.type); if (days > b.left) { toast(`Only ${b.left} day(s) of ${LEAVE_TYPES[d.type]} left`, 'err'); return false; }
    if (DB.leaves.some(l => l.emp === me().id && ['Pending', 'Approved'].includes(l.status) && d.from <= l.to && d.to >= l.from)) { toast('You already have leave on those dates', 'err'); return false; }
    const ap = me().mgr || 'E001'; DB.leaves.unshift({ id: uid('L'), emp: me().id, type: d.type, from: d.from, to: d.to, days, status: 'Pending', reason: d.reason, ts: TODAY(), approver: ap }); notify(ap, `${me().name} applied for ${days} day(s) of ${LEAVE_TYPES[d.type]}`); log('Applied leave'); save(); render(); toast('Leave request sent to ' + emp(ap).name);
  }, 'Submit request');
  const upd = () => { const f = m.querySelector('[name=from]').value, t = m.querySelector('[name=to]').value, ty = m.querySelector('[name=type]').value, b = leaveBalance(me().id, ty); m.querySelector('#lvinfo').innerHTML = f && t && t >= f ? `<span class="badge acc">${leaveDays(f, t)} working day(s)</span> <span class="muted small">Balance: ${b.left === Infinity ? 'unlimited' : b.left}</span>` : ''; }; m.addEventListener('input', upd); upd();
};
ACT.lv_cancel = el => confirmBox('Cancel this leave request?', () => { const l = DB.leaves.find(x => x.id === el.dataset.id); l.status = 'Cancelled'; save(); render(); toast('Leave cancelled'); });

/* ================= PAYROLL ================= */
const monthsBack = n => { const T = TODAY(), out = []; let y = +T.slice(0, 4), m = +T.slice(5, 7); for (let i = 0; i < n; i++) { out.push(`${y}-${String(m).padStart(2, '0')}`); m--; if (!m) { m = 12; y--; } } return out; };
PAGE_FN.payroll = () => {
  const u = me(), tabs = [['slips', 'My payslips'], ['claims', 'Expense claims'], ['ctc', 'My salary']]; if (can('pay.run')) tabs.splice(1, 0, ['run', 'Run payroll']); tabs.push(['loans', 'Loans & advances']); if (can('pay.components')) tabs.push(['setup', 'Salary components']); const tab = tabOf('pay', 'slips'); let body = '';
  if (tab === 'slips') { const ms = monthsBack(7).filter(ym => isReleased(ym, u.id) && ym + '-28' >= u.joined.slice(0, 7) + '-01'); body = `<div class="card pad0"><table><thead><tr><th>Month</th><th>Gross</th><th>Deductions</th><th>Net pay</th><th></th></tr></thead><tbody>${ms.map(ym => { const p = payslip(u.id, ym); return `<tr><td><b>${monthName(ym)}</b></td><td>${inr(p.gross)}</td><td>${inr(p.deductions)}</td><td><b>${inr(p.net)}</b></td><td style="text-align:right"><button class="btn sm" data-act="slip" data-id="${u.id}" data-ym="${ym}">${ic('eye')} View</button></td></tr>`; }).join('') || '<tr><td colspan="5" class="empty">No payslips yet</td></tr>'}</tbody></table></div>`; }
  if (tab === 'run') {
    const ym = S.payYm || ymOf(TODAY()), run = DB.payruns[ym], first = ym + '-01', last = addDays(addDays(first, 32).slice(0, 8) + '01', -1); const es = DB.employees.filter(e => e.joined <= last && !(e.exit && e.exit < first) && e.status !== 'Exited' || (e.exit && e.exit >= first && e.joined <= last)); const ps = es.map(e => payslip(e.id, ym));
    const tot = k => sum(ps, p => p[k]);
    body = `<div class="toolbar"><select class="select" data-chg="payym">${monthsBack(6).map(m => `<option value="${m}" ${m === ym ? 'selected' : ''}>${monthName(m)}</option>`).join('')}</select> ${run ? statusBadge(run.status) : '<span class="badge warn">Draft</span>'}<span class="right row"><button class="btn" data-act="pay_csv" data-ym="${ym}">${ic('download')} Bank file</button>${run?.status === 'Paid' ? '' : `<button class="btn primary" data-act="pay_run" data-ym="${ym}">Approve &amp; pay</button>`}</span></div>
    <div class="grid g4" style="margin-bottom:16px">${[[inr(tot('gross')), 'Gross pay'], [inr(tot('deductions')), 'Deductions'], [inr(tot('net')), 'Net payable'], [ps.length, 'Employees paid']].map(k => `<div class="card kpi"><span class="v" style="font-size:22px">${k[0]}</span><span class="l">${k[1]}</span></div>`).join('')}</div>
    <div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Gross</th><th>PF</th><th>TDS</th><th>LOP days</th><th>Net</th><th></th></tr></thead><tbody>${ps.map(p => `<tr><td>${person(emp(p.id))}</td><td>${inr(p.gross)}</td><td>${inr(p.pf)}</td><td>${inr(p.ded.find(d => d[0].includes('TDS'))[1])}</td><td>${p.lop || '—'}</td><td><b>${inr(p.net)}</b></td><td><button class="btn sm" data-act="slip" data-id="${p.id}" data-ym="${ym}">View</button></td></tr>`).join('')}</tbody></table></div><p class="small muted">Illustrative calculation: Basic 40% of CTC, HRA 20%, PF 12% of basic (capped ₹15,000 wage), professional tax ₹200, TDS on India new-regime slabs with ₹75,000 standard deduction. Verify against your statutory advisor before real use.</p>`;
  }
  if (tab === 'claims') { const list = DB.claims.filter(c => c.emp === u.id || canApproveClaim(c) || isHR()); body = `<div class="row" style="margin-bottom:12px"><span class="muted">Submit reimbursements — approved claims are added to the next payslip.</span><button class="btn primary right" data-act="claim_new">${ic('plus')} New claim</button></div><div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Category</th><th>Date</th><th>Amount</th><th>Description</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c => `<tr><td>${person(emp(c.emp))}</td><td>${esc(c.cat)}</td><td>${fmtShort(c.date)}</td><td><b>${inr(c.amount)}</b></td><td>${c.title ? '<b>' + esc(c.title) + '</b><div class="muted small">' + esc(c.desc) + '</div>' : esc(c.desc)}${c.pay ? ' <span class="badge">' + esc(c.pay) + '</span>' : ''}${c.file ? ' <span title="' + esc(c.file) + '">📎</span>' : ''}</td><td>${statusBadge(c.status)}</td><td class="nowrap">${canApproveClaim(c) ? `<button class="btn sm primary" data-act="appr" data-t="claim" data-id="${c.id}" data-v="Approved">Approve</button> <button class="btn sm danger" data-act="appr" data-t="claim" data-id="${c.id}" data-v="Rejected">Reject</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">No claims</td></tr>'}</tbody></table></div>`; }
  if (tab === 'ctc') { const p = payslip(u.id, ymOf(TODAY())); body = `<div class="grid g2"><div class="card"><div class="kpi"><span class="v">${inr(u.salary)}</span><span class="l">Annual CTC</span></div><div style="margin-top:12px">${donut([{ l: 'Basic', v: Math.round(p.earn[0][1] * 12 / 1000), c: COLORS[0] }, { l: 'HRA', v: Math.round(p.earn[1][1] * 12 / 1000), c: COLORS[2] }, { l: 'Allowances', v: Math.round(sum(p.earn.slice(2).filter(x => x[0] !== 'Reimbursements'), x => x[1]) * 12 / 1000), c: COLORS[1] }], 140)}<div class="small muted">Values in ₹ thousands / year</div></div></div>
    <div class="card"><header><h3>Monthly take-home estimate</h3></header><table><tbody><tr><td>Gross</td><td style="text-align:right">${inr(p.gross)}</td></tr>${p.ded.filter(d => !d[0].startsWith('Loss')).map(d => `<tr><td>− ${d[0]}</td><td style="text-align:right">${inr(d[1])}</td></tr>`).join('')}<tr><td><b>Net (before LOP)</b></td><td style="text-align:right"><b>${inr(p.gross - sum(p.ded.filter(d => !d[0].startsWith('Loss')), d => d[1]))}</b></td></tr></tbody></table></div></div>`; }
  if (TABX.pay[tab]) body = TABX.pay[tab](); return head('Payroll', 'Payslips, salary structure and reimbursements') + tabsBar('pay', tabs, 'slips') + body;
};
CHG.payym = el => { S.payYm = el.value; render(); };
ACT.slip = el => {
  const p = payslip(el.dataset.id, el.dataset.ym), e = emp(p.id), n = Math.max(p.earn.length, p.ded.length);
  modal('Payslip', `<div class="payslip"><div class="row between"><div><h2>${esc(coLines()[0])}</h2>${coLines().slice(1).map(x => `<div class="muted small">${esc(x)}</div>`).join('')}<div class="small" style="margin-top:4px"><b>Payslip for ${monthName(p.ym)}</b></div></div><span class="logo" style="color:#06201d">${ic('spark')}</span></div>
  <div class="grid g2" style="margin:14px 0;gap:6px"><div><span class="muted">Employee</span> <b>${esc(e.name)}</b></div><div><span class="muted">ID</span> <b>${e.id}</b></div><div><span class="muted">Designation</span> <b>${esc(e.title)}</b></div><div><span class="muted">Department</span> <b>${esc(e.dept)}</b></div><div><span class="muted">Working days</span> <b>${p.work}</b></div><div><span class="muted">LOP days</span> <b>${p.lop}</b></div></div>
  <table><thead><tr><th>Earnings</th><th style="text-align:right">₹</th><th>Deductions</th><th style="text-align:right">₹</th></tr></thead><tbody>${Array.from({ length: n }, (_, i) => `<tr><td>${p.earn[i]?.[0] || ''}</td><td style="text-align:right">${p.earn[i] ? Math.round(p.earn[i][1]).toLocaleString('en-IN') : ''}</td><td>${p.ded[i]?.[0] || ''}</td><td style="text-align:right">${p.ded[i] ? Math.round(p.ded[i][1]).toLocaleString('en-IN') : ''}</td></tr>`).join('')}<tr class="tot"><td>Gross</td><td style="text-align:right">${Math.round(p.gross).toLocaleString('en-IN')}</td><td>Total deductions</td><td style="text-align:right">${Math.round(p.deductions).toLocaleString('en-IN')}</td></tr></tbody></table>
  <div class="row between" style="margin-top:14px;padding:14px;border-radius:10px;background:var(--accent-soft)"><b>Net pay</b><b style="font-size:22px">${inr(p.net)}</b></div><p class="small muted" style="margin-bottom:0">System-generated payslip — no signature required.</p></div>
  <div class="row" style="margin-top:12px"><button type="button" class="btn" onclick="window.print()">${ic('printer')} Print / Save PDF</button></div>`, null, '', true);
};
ACT.pay_run = el => confirmBox(`Approve and pay ${monthName(el.dataset.ym)}? Employees will be notified that their payslip is ready.`, () => { DB.payruns[el.dataset.ym] = { status: 'Paid', ts: TODAY(), by: me().id }; activeEmps().forEach(e => notify(e.id, `💰 Your payslip for ${monthName(el.dataset.ym)} is ready`)); log('Paid payroll ' + el.dataset.ym); save(); render(); toast('Payroll processed'); });
ACT.pay_csv = el => { const ym = el.dataset.ym; download(`bank-file-${ym}.csv`, csv([['Employee ID', 'Name', 'Net pay (INR)'], ...activeEmps().map(e => { const p = payslip(e.id, ym); return [e.id, e.name, Math.round(p.net)]; })])); };
ACT.claim_new = () => modal('New expense claim', `<div class="form-grid">${sel('Category', 'cat', ['Travel', 'Meals', 'Internet', 'Equipment', 'Training', 'Other'])}${fld('Amount (₹)', 'amount', '', 'number', 'min="1" required')}${fld('Expense date', 'date', TODAY(), 'date', `max="${TODAY()}" required`, 'full')}<label class="f full">Description<textarea class="input" name="desc" rows="2" required></textarea></label></div>`, d => { DB.claims.unshift({ id: uid('X'), emp: me().id, ...d, amount: +d.amount, status: 'Pending' }); notify(me().mgr || 'E002', `${me().name} submitted an expense claim`); save(); render(); toast('Claim submitted'); }, 'Submit');

/* ================= RECRUITMENT ================= */
PAGE_FN.recruitment = () => {
  const tab = tabOf('rec', 'pipe'); let body = ''; const jobs = DB.jobs;
  if (tab === 'pipe') {
    const cs = DB.cands.filter(c => !S.jobF || c.job === S.jobF);
    body = `<div class="toolbar"><select class="select" data-chg="jobf"><option value="">All open roles</option>${jobs.map(j => `<option value="${j.id}" ${S.jobF === j.id ? 'selected' : ''}>${esc(j.title)}</option>`).join('')}</select><span class="muted small">Drag cards between stages</span></div>
    <div class="kanban">${STAGES.map(s => `<div class="kcol" data-stage="${s}"><h4><span>${s}</span><span>${cs.filter(c => c.stage === s).length}</span></h4>${cs.filter(c => c.stage === s).map(c => { const j = jobs.find(x => x.id === c.job); return `<div class="kcard" draggable="true" data-cid="${c.id}" data-act="cand_open" data-id="${c.id}"><b>${esc(c.name)}</b><div class="muted small">${esc(j?.title || '')}</div><div class="row between" style="margin-top:6px"><span style="color:var(--amber);font-size:12px">${stars(c.rating)}</span><span class="badge">${esc(c.source)}</span></div>${c.interview && s === 'Interview' ? `<div class="badge info" style="margin-top:6px">🗓 ${fmtShort(c.interview)}</div>` : ''}${s === 'Hired' && !c.hired ? `<button class="btn sm primary" style="margin-top:6px" data-act="cand_hire" data-id="${c.id}">Convert to employee</button>` : ''}</div>`; }).join('')}</div>`).join('')}</div>`;
  } else body = `<div class="card pad0 tablewrap"><table><thead><tr><th>Role</th><th>Department</th><th>Location</th><th>Openings</th><th>Candidates</th><th>Hiring manager</th><th>Status</th></tr></thead><tbody>${jobs.map(j => `<tr><td><b>${esc(j.title)}</b></td><td>${esc(j.dept)}</td><td>${esc(j.loc)}</td><td>${j.openings}</td><td>${DB.cands.filter(c => c.job === j.id).length}</td><td>${esc(emp(j.owner)?.name)}</td><td>${statusBadge(j.status)} ${isHR() ? `<button class="btn sm" data-act="job_toggle" data-id="${j.id}">${j.status === 'Open' ? 'Pause' : 'Open'}</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
  const conv = DB.cands.length ? Math.round(DB.cands.filter(c => c.stage === 'Hired').length / DB.cands.length * 100) : 0;
  return head('Recruitment', `${sum(jobs.filter(j => j.status === 'Open'), j => j.openings)} open positions · ${DB.cands.length} candidates · ${conv}% hired`, `${isHR() ? `<button class="btn" data-act="job_new">${ic('plus')} New job</button>` : ''}<button class="btn primary" data-act="cand_new">${ic('plus')} Add candidate</button>`) + tabsBar('rec', [['pipe', 'Pipeline'], ['jobs', 'Jobs']], 'pipe') + body;
};
CHG.jobf = el => { S.jobF = el.value; render(); };
ACT.job_new = () => modal('New job opening', `<div class="form-grid">${fld('Job title', 'title', '', 'text', 'required', 'full')}${sel('Department', 'dept', DEPTS)}${fld('Location', 'loc', '')}${fld('Openings', 'openings', 1, 'number', 'min="1"')}${sel('Hiring manager', 'owner', activeEmps().map(e => [e.id, e.name]))}</div>`, d => { DB.jobs.push({ id: uid('J'), ...d, openings: +d.openings, status: 'Open' }); log('Opened job ' + d.title); save(); render(); toast('Job created'); }, 'Create job');
ACT.job_toggle = el => { const j = DB.jobs.find(x => x.id === el.dataset.id); j.status = j.status === 'Open' ? 'On hold' : 'Open'; save(); render(); };
ACT.cand_new = () => modal('Add candidate', `<div class="form-grid">${fld('Name', 'name', '', 'text', 'required')}${fld('Email', 'email', '', 'email')}${sel('Job', 'job', DB.jobs.map(j => [j.id, j.title]), S.jobF)}${sel('Source', 'source', ['LinkedIn', 'Referral', 'Careers page', 'Naukri', 'Agency', 'Other'])}${sel('Rating', 'rating', [1, 2, 3, 4, 5], 3)}</div>`, d => { DB.cands.push({ id: uid('C'), ...d, rating: +d.rating, stage: 'Applied', notes: '', interview: '' }); save(); render(); toast('Candidate added'); }, 'Add');
ACT.cand_open = (el, e) => {
  if (e.target.closest('[data-act=cand_hire]')) return; const c = DB.cands.find(x => x.id === el.dataset.id);
  modal(esc(c.name), `<div class="form-grid">${sel('Stage', 'stage', STAGES, c.stage)}${sel('Rating', 'rating', [1, 2, 3, 4, 5], c.rating)}${fld('Interview date', 'interview', c.interview, 'date', '', 'full')}<label class="f full">Notes<textarea class="input" name="notes" rows="3">${esc(c.notes)}</textarea></label></div><button type="button" class="btn danger sm" style="margin-top:12px" data-act="cand_del" data-id="${c.id}">Reject &amp; remove</button>`, d => { Object.assign(c, d, { rating: +d.rating }); if (d.stage === 'Interview' && d.interview) notify(DB.jobs.find(j => j.id === c.job)?.owner || 'E001', `Interview scheduled with ${c.name} on ${fmtShort(d.interview)}`); save(); render(); toast('Candidate updated'); });
};
ACT.cand_del = el => { DB.cands = DB.cands.filter(c => c.id !== el.dataset.id); el.closest('.modal-bg').remove(); save(); render(); toast('Candidate removed'); };
ACT.cand_hire = el => {
  const c = DB.cands.find(x => x.id === el.dataset.id), j = DB.jobs.find(x => x.id === c.job);
  modal('Convert to employee', `<div class="form-grid">${fld('Name', 'name', c.name, 'text', 'required')}${fld('Email', 'email', c.email, 'email', 'required')}${fld('Job title', 'title', j.title, 'text', 'required')}${sel('Department', 'dept', DEPTS, j.dept)}${sel('Reports to', 'mgr', activeEmps().map(e => [e.id, e.name]), j.owner)}${fld('Annual CTC (₹)', 'salary', 1200000, 'number', 'required')}${fld('Joining date', 'joined', addDays(TODAY(), 14), 'date', 'required')}</div>`, d => {
    if (DB.employees.some(x => x.email === d.email)) { toast('Email already exists', 'err'); return false; } const id = 'E' + String(DB.employees.length + 1).padStart(3, '0');
    DB.employees.push({ id, ...d, salary: +d.salary, role: 'employee', pass: tempPassFor(id), status: 'Onboarding', dob: '', gender: '', phone: '', loc: j.loc, skills: [], color: COLORS[DB.employees.length % COLORS.length], emergency: '', exit: null }); DB.att[id] = {};
    ONB_TASKS.forEach(t => DB.tasks.push({ id: uid('O'), emp: id, title: t[0], owner: t[1], done: false })); c.hired = true; log('Hired ' + d.name); save(); render(); toast(d.name + ' is now an employee with an onboarding plan');
  }, 'Create employee');
};
document.addEventListener('dragstart', e => { const c = e.target.closest?.('[data-cid]'); if (c) { e.dataTransfer.setData('text/plain', c.dataset.cid); e.dataTransfer.effectAllowed = 'move'; } });
document.addEventListener('dragover', e => { const k = e.target.closest?.('.kcol'); if (k) { e.preventDefault(); $$('.kcol.over').forEach(x => x.classList.remove('over')); k.classList.add('over'); } });
document.addEventListener('dragend', () => $$('.kcol.over').forEach(x => x.classList.remove('over')));
document.addEventListener('drop', e => { const k = e.target.closest?.('.kcol'); if (!k) return; e.preventDefault(); const c = DB.cands.find(x => x.id === e.dataTransfer.getData('text/plain')); if (!c) return; c.stage = k.dataset.stage; save(); render(); if (c.stage === 'Hired') toast('Moved to Hired — convert to employee when ready'); });

/* ================= PERFORMANCE ================= */
PAGE_FN.performance = () => {
  const u = me(), tab = tabOf('perf', 'goals'); let body = '';
  if (tab === 'goals') {
    const opts = [['me', 'My goals']]; if (isMgr()) opts.push(['team', 'My team']); if (isHR()) opts.push(['all', 'Everyone']); const sc = S.goalScope && opts.some(o => o[0] === S.goalScope) ? S.goalScope : 'me';
    const ids = sc === 'me' ? [u.id] : sc === 'team' ? reportsOf(u.id).map(e => e.id) : activeEmps().map(e => e.id); const gs = DB.goals.filter(g => ids.includes(g.emp));
    body = `<div class="toolbar">${opts.length > 1 ? `<select class="select" data-chg="goalscope">${opts.map(o => `<option value="${o[0]}" ${sc === o[0] ? 'selected' : ''}>${o[1]}</option>`).join('')}</select>` : ''}<button class="btn primary right" data-act="goal_new">${ic('plus')} New goal</button></div>
    <div class="card pad0 tablewrap"><table><thead><tr>${sc !== 'me' ? '<th>Employee</th>' : ''}<th>Goal</th><th style="width:30%">Progress</th><th>Due</th><th></th></tr></thead><tbody>${gs.map(g => `<tr>${sc !== 'me' ? `<td>${person(emp(g.emp))}</td>` : ''}<td>${esc(g.title)}</td><td><div class="row"><div class="progress" style="flex:1"><i style="width:${g.progress}%"></i></div><b style="width:38px">${g.progress}%</b></div>${(g.emp === u.id || isHR()) ? `<input type="range" min="0" max="100" step="5" value="${g.progress}" data-chg="goalp" data-id="${g.id}" style="width:100%;margin-top:4px">` : ''}</td><td>${fmtShort(g.due)}</td><td>${g.emp === u.id || isHR() ? `<button class="btn sm danger" data-act="goal_del" data-id="${g.id}">✕</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No goals yet — set your first one.</td></tr>'}</tbody></table></div>`;
  }
  if (tab === 'rev') {
    const list = (isHR() ? activeEmps().filter(e => e.status === 'Active') : [u, ...reportsOf(u.id)]).map(e => ({ e, r: DB.reviews.find(r => r.emp === e.id) })).filter(x => x.r), done = list.filter(x => x.r.self && x.r.mgr).length;
    body = `<div class="card" style="margin-bottom:16px"><div class="row between"><div><b>H2 2026 review cycle</b><div class="muted small">Due ${fmtDate(addDays(TODAY(), 25))}</div></div><div style="min-width:220px"><div class="small muted">${done}/${list.length} complete</div><div class="progress"><i style="width:${list.length ? done / list.length * 100 : 0}%"></i></div></div></div></div>
    <div class="card pad0 tablewrap"><table><thead><tr><th>Employee</th><th>Self rating</th><th>Manager rating</th><th>Status</th><th></th></tr></thead><tbody>${list.map(({ e, r }) => `<tr><td>${person(e)}</td><td>${r.self ? stars(r.self) : '—'}</td><td>${r.mgr ? stars(r.mgr) : '—'}</td><td>${statusBadge(r.self && r.mgr ? 'Approved' : 'Pending').replace('Approved', 'Complete')}</td><td>${e.id === u.id && !r.self ? `<button class="btn sm primary" data-act="rev" data-id="${e.id}" data-k="self">Self review</button>` : ''}${e.id !== u.id && !r.mgr && (isHR() || e.mgr === u.id) ? `<button class="btn sm primary" data-act="rev" data-id="${e.id}" data-k="mgr">Rate</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
  }
  if (tab === 'kudos') body = `<div class="row" style="margin-bottom:12px"><span class="muted">Recognise great work — it shows on everyone's dashboard.</span><button class="btn primary right" data-act="kudo_new">${ic('award')} Give kudos</button></div><div class="grid g2">${DB.kudos.map(k => `<div class="card"><div class="row">${avatar(emp(k.from), 'sm')}<b>${esc(emp(k.from)?.name)}</b> <span class="muted">→</span> ${avatar(emp(k.to), 'sm')}<b>${esc(emp(k.to)?.name)}</b></div><p style="margin:10px 0"> “${esc(k.msg)}”</p><div class="row between"><span class="badge vio">🏆 ${esc(k.badge)}</span><span class="muted small">${fmtShort(k.ts)}</span></div></div>`).join('')}</div>`;
  return head('Performance', 'Goals, reviews and recognition') + tabsBar('perf', [['goals', 'Goals (OKRs)'], ['rev', 'Reviews'], ['eval', 'Evaluations'], ['kudos', 'Kudos']], 'goals') + (TABX.perf[tab] ? TABX.perf[tab]() : body);
};
CHG.goalscope = el => { S.goalScope = el.value; render(); }; CHG.goalp = el => { DB.goals.find(g => g.id === el.dataset.id).progress = +el.value; save(); render(); };
ACT.goal_del = el => { DB.goals = DB.goals.filter(g => g.id !== el.dataset.id); save(); render(); };
ACT.goal_new = () => modal('New goal', `<div class="form-grid">${fld('Goal', 'title', '', 'text', 'required', 'full')}${fld('Due date', 'due', addDays(TODAY(), 60), 'date')}${fld('Starting progress %', 'progress', 0, 'number', 'min="0" max="100"')}</div>`, d => { DB.goals.unshift({ id: uid('G'), emp: me().id, title: d.title, due: d.due, progress: +d.progress, cycle: 'H2 2026' }); save(); render(); toast('Goal added'); });
ACT.rev = el => { const r = DB.reviews.find(x => x.emp === el.dataset.id), k = el.dataset.k; modal(k === 'self' ? 'Self review' : 'Rate ' + esc(emp(r.emp).name), `<div class="col">${sel('Overall rating', 'rating', [[5, '5 — Outstanding'], [4, '4 — Exceeds expectations'], [3, '3 — Meets expectations'], [2, '2 — Needs improvement'], [1, '1 — Unsatisfactory']], 4)}<label class="f">Comments<textarea class="input" name="c" rows="3"></textarea></label></div>`, d => { r[k] = +d.rating; if (d.c) r.comment = d.c; if (k === 'mgr') notify(r.emp, 'Your manager completed your review'); save(); render(); toast('Review saved'); }); };
ACT.kudo_new = () => modal('Give kudos', `<div class="col">${sel('Who deserves it?', 'to', activeEmps().filter(e => e.id !== me().id).map(e => [e.id, e.name]))}${sel('Badge', 'badge', ['Above & Beyond', 'Team Player', 'Customer Hero', 'Creative Spark', 'Problem Solver', 'Mentor'])}<label class="f">Message<textarea class="input" name="msg" rows="3" required></textarea></label></div>`, d => { DB.kudos.unshift({ id: uid('K'), from: me().id, ...d, ts: TODAY() }); notify(d.to, `🏆 ${me().name} gave you kudos: ${d.badge}`); save(); render(); toast('Kudos sent!'); }, 'Send kudos');

/* ================= ONBOARDING ================= */
PAGE_FN.onboarding = () => {
  const u = me(); let ids = [...new Set(DB.tasks.map(t => t.emp))]; if (!isHR()) ids = ids.filter(i => i === u.id);
  const cards = ids.map(i => { const e = emp(i), ts = DB.tasks.filter(t => t.emp === i), off = ts.some(t => t.off), done = ts.filter(t => t.done).length, pct = Math.round(done / ts.length * 100);
    return `<div class="card"><div class="row">${avatar(e)}<div style="flex:1"><b>${esc(e.name)}</b> <span class="badge ${off ? 'warn' : 'info'}">${off ? 'Offboarding' : 'Onboarding'}</span><div class="muted small">${esc(e.title)} · ${off ? 'last day ' + fmtShort(e.exit) : 'joined ' + fmtShort(e.joined)}</div></div><b>${pct}%</b></div><div class="progress" style="margin:10px 0"><i style="width:${pct}%"></i></div>
    ${ts.map(t => `<label class="row" style="padding:5px 0;cursor:pointer"><input type="checkbox" ${t.done ? 'checked' : ''} data-chg="task" data-id="${t.id}" ${(isHR() || (t.owner === 'Employee' && t.emp === u.id)) ? '' : 'disabled'}><span style="flex:1;${t.done ? 'text-decoration:line-through;opacity:.55' : ''}">${esc(t.title)}</span><span class="badge ${t.owner === 'Employee' ? 'acc' : t.owner === 'IT' ? 'info' : 'vio'}">${t.owner}</span></label>`).join('')}</div>`; }).join('');
  return head('Onboarding & exits', 'Checklists keep every joiner and leaver on track') + (cards ? `<div class="grid g2">${cards}</div>` : '<div class="card empty">🎉 Nothing pending. New joiners and leavers will appear here.</div>');
};
CHG.task = el => { const t = DB.tasks.find(x => x.id === el.dataset.id); t.done = el.checked; const ts = DB.tasks.filter(x => x.emp === t.emp); if (ts.every(x => x.done)) { toast('All tasks complete!'); const e = emp(t.emp); if (e.status === 'Onboarding') { e.status = 'Active'; log(e.name + ' is now active'); } } save(); render(); };

/* ================= HELPDESK ================= */
PAGE_FN.helpdesk = () => {
  const u = me(), list = DB.tickets.filter(t => isHR() || t.emp === u.id), open = list.filter(t => t.status !== 'Resolved').length;
  return head('Helpdesk', `${open} open of ${list.length} tickets`, `<button class="btn primary" data-act="tk_new">${ic('plus')} New ticket</button>`) + `<div class="card pad0 tablewrap"><table><thead><tr><th>ID</th><th>Subject</th><th>Raised by</th><th>Category</th><th>Priority</th><th>Status</th></tr></thead><tbody>${list.map(t => `<tr class="click" data-act="tk_open" data-id="${t.id}"><td>${t.id}</td><td><b>${esc(t.subject)}</b></td><td>${person(emp(t.emp))}</td><td>${esc(t.cat)}</td><td><span class="badge ${t.priority === 'High' ? 'bad' : t.priority === 'Medium' ? 'warn' : ''}">${t.priority}</span></td><td>${statusBadge(t.status)}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No tickets</td></tr>'}</tbody></table></div>`;
};
ACT.tk_new = () => modal('Raise a ticket', `<div class="form-grid">${fld('Subject', 'subject', '', 'text', 'required', 'full')}${sel('Category', 'cat', ['Payroll', 'Leave', 'IT', 'Benefits', 'Policy', 'Other'])}${sel('Priority', 'priority', ['Low', 'Medium', 'High'], 'Medium')}<label class="f full">Details<textarea class="input" name="desc" rows="3" required></textarea></label></div>`, d => { const t = { id: 'T-' + (1000 + DB.tickets.length + 1), emp: me().id, ...d, status: 'Open', ts: TODAY(), replies: [] }; DB.tickets.unshift(t); DB.employees.filter(e => e.role === 'hr').forEach(h => notify(h.id, `New ticket ${t.id}: ${t.subject}`)); save(); render(); toast('Ticket ' + t.id + ' created'); }, 'Submit');
ACT.tk_open = el => {
  const t = DB.tickets.find(x => x.id === el.dataset.id);
  modal(`${t.id} · ${esc(t.subject)}`, `<div class="muted small">${esc(emp(t.emp).name)} · ${esc(t.cat)} · ${fmtDate(t.ts)}</div><p>${esc(t.desc)}</p><div class="list">${t.replies.map(r => `<div><b>${esc(emp(r.by)?.name)}</b> <span class="muted small">${fmtShort(r.ts)}</span><div>${esc(r.msg)}</div></div>`).join('')}</div><div class="form-grid" style="margin-top:12px"><label class="f full">Reply<textarea class="input" name="reply" rows="2"></textarea></label>${isHR() ? sel('Status', 'status', ['Open', 'In progress', 'Resolved'], t.status, 'full') : ''}</div>`, d => { if (d.reply?.trim()) { t.replies.push({ by: me().id, msg: d.reply, ts: TODAY() }); if (t.emp !== me().id) notify(t.emp, `New reply on ${t.id}`); } if (d.status) t.status = d.status; save(); render(); toast('Ticket updated'); }, 'Update');
};

/* ================= DOCUMENTS ================= */
const POLICIES = [['Code of Conduct', 'How we treat each other and our customers.'], ['Leave & Attendance Policy', 'Quotas, approvals, regularization and holidays.'], ['Work From Home Policy', 'Eligibility, expectations and equipment.'], ['POSH — Anti-harassment Policy', 'Zero tolerance and how to raise a complaint.'], ['Information Security Policy', 'Passwords, devices, data handling.'], ['Expense & Travel Policy', 'What is reimbursable and the limits.']];
const docsPolicies = () => {
  const u = me(), ack = DB.acks[u.id] || [];
  return head('Policies & documents', 'Read, acknowledge and download', `<button class="btn" data-act="letter">${ic('file')} Employment letter</button>`) + `<div class="grid g2">${POLICIES.map((p, i) => { const n = Object.values(DB.acks).filter(a => a.includes(i)).length; return `<div class="card"><div class="row"><span class="logo" style="color:#06201d">${ic('file')}</span><div style="flex:1"><b>${p[0]}</b><div class="muted small">${p[1]}</div></div></div><div class="row between" style="margin-top:12px">${ack.includes(i) ? '<span class="badge ok">✓ Acknowledged</span>' : `<button class="btn sm primary" data-act="ack" data-i="${i}">I have read &amp; agree</button>`}${isHR() ? `<span class="muted small">${n}/${activeEmps().length} acknowledged</span>` : ''}</div></div>`; }).join('')}</div>`;
};
ACT.ack = el => { (DB.acks[me().id] ||= []).push(+el.dataset.i); log('Acknowledged policy ' + POLICIES[+el.dataset.i][0]); save(); render(); toast('Thanks — recorded'); };
ACT.letter = () => { const u = me(); download(`employment-letter-${u.id}.txt`, `${coLines().join('\n')}\n\nDate: ${fmtDate(TODAY())}\n\nTO WHOMSOEVER IT MAY CONCERN\n\nThis is to certify that ${u.name} (${u.id}) has been employed with ${DB.company} since ${fmtDate(u.joined)} as ${u.title} in the ${u.dept} department, and is currently in service.\n\nFor ${coLines()[0]}\n${CO.signatory ? CO.signatory + (CO.signatoryTitle ? ', ' + CO.signatoryTitle : '') : 'Human Resources'}`, 'text/plain'); toast('Letter downloaded'); };

/* ================= ORG ================= */
PAGE_FN.org = () => {
  const node = e => { const k = reportsOf(e.id); const row = `<a href="#/employees/${e.id}" style="color:inherit" class="row">${avatar(e)}<div><b>${esc(e.name)}</b><div class="muted small">${esc(e.title)}${k.length ? ' · ' + k.length + ' reports' : ''}</div></div></a>`; return k.length ? `<details open><summary>${row}</summary>${k.map(node).join('')}</details>` : `<div class="leaf">${row}</div>`; };
  const roots = activeEmps().filter(e => !e.mgr || !emp(e.mgr) || emp(e.mgr).status === 'Exited');
  return head('Org chart', 'Reporting lines across the company') + `<div class="card org">${roots.map(node).join('')}</div>`;
};

/* ================= REPORTS ================= */
const reportsAnalytics = () => {
  const es = scope(), T = TODAY(); const dept = DEPTS.map((d, i) => ({ l: d, v: es.filter(e => e.dept === d).length, c: COLORS[i] })).filter(d => d.v);
  const gender = [{ l: 'Women', v: es.filter(e => e.gender === 'F').length, c: COLORS[4] }, { l: 'Men', v: es.filter(e => e.gender === 'M').length, c: COLORS[2] }, { l: 'Other', v: es.filter(e => e.gender === 'O').length, c: COLORS[6] }].filter(d => d.v);
  const ten = [['<1y', 0, 1], ['1–2y', 1, 2], ['2–4y', 2, 4], ['4y+', 4, 99]].map(([l, a, b]) => ({ l, v: es.filter(e => { const y = daysBetween(e.joined, T) / 365; return y >= a && y < b; }).length }));
  const cost = dept.map(d => ({ l: d.l, v: Math.round(sum(es.filter(e => e.dept === d.l), e => e.salary) / 100000), c: d.c }));
  const days = []; for (let k = 29; k >= 1; k--) { const d = addDays(T, -k); const base = es.filter(e => !['weekend', 'holiday', 'na'].includes(dayStatus(e.id, d).s)); if (!base.length) continue; days.push({ l: fmtShort(d), v: Math.round(base.filter(e => ['present', 'late', 'wfh'].includes(dayStatus(e.id, d).s)).length / base.length * 100) }); }
  const exits = DB.employees.filter(e => e.status === 'Exited').length, attr = (exits / Math.max(1, DB.employees.length) * 100).toFixed(1), avgTen = (sum(es, e => daysBetween(e.joined, T)) / 365 / Math.max(1, es.length)).toFixed(1);
  const lv = sum(DB.leaves.filter(l => l.status === 'Approved' && es.some(e => e.id === l.emp)), l => l.days);
  return head('Reports & analytics', isHR() ? 'Company-wide workforce insight' : 'Insight for your team', `<button class="btn" data-act="emp_csv">${ic('download')} Employees CSV</button><button class="btn" data-act="att_csv">${ic('download')} Attendance CSV</button>`)
    + `<div class="grid g4" style="margin-bottom:16px">${[[es.length, 'Headcount'], [inr(sum(es, e => e.salary) / 12), 'Monthly payroll cost'], [avgTen + ' yrs', 'Average tenure'], [attr + '%', 'Attrition (all time)']].map(k => `<div class="card kpi"><span class="v" style="font-size:24px">${k[0]}</span><span class="l">${k[1]}</span></div>`).join('')}</div>
  <div class="grid g2"><div class="card"><header><h3>Headcount by department</h3></header>${barChart(dept)}</div><div class="card"><header><h3>Gender diversity</h3></header>${donut(gender)}</div>
  <div class="card"><header><h3>Tenure distribution</h3></header>${barChart(ten, { color: 'var(--violet)' })}</div><div class="card"><header><h3>Annual cost by department</h3><span class="muted small">₹ lakh</span></header>${barChart(cost, { fmt: x => x + 'L' })}</div></div>
  <div class="card" style="margin-top:16px"><header><h3>Attendance rate — last 30 days</h3><span class="muted small">${lv} leave days approved this year</span></header>${lineChart(days, { fmt: x => x + '%' })}</div>`;
};

/* ================= SETTINGS ================= */
PAGE_FN.settings = () => {
  const q = DB.settings.quota;
  return head('Settings', 'Workspace configuration (admin only)') + `<div class="grid g2"><form class="card" id="setf" data-act="noop"><header><h3>Company &amp; policy</h3></header><div class="form-grid">${fld('Company name', 'company', DB.company, 'text', '', 'full')}${fld('Casual leave / yr', 'CL', q.CL, 'number')}${fld('Sick leave / yr', 'SL', q.SL, 'number')}${fld('Earned leave / yr', 'EL', q.EL, 'number')}${fld('Comp-off / yr', 'CO', q.CO, 'number')}${fld('Late after (HH:MM)', 'lateAfter', DB.settings.lateAfter, 'time', '', 'full')}</div><button class="btn primary" style="margin-top:14px">Save settings</button></form>
  <div class="card"><header><h3>Data</h3></header><div class="col"><p class="muted" style="margin:0">All data lives in this browser. Export a backup, import one, or erase everything and start again.</p><div class="row wrap"><button class="btn" data-act="exp">${ic('download')} Export JSON</button><label class="btn" style="cursor:pointer">Import JSON<input type="file" accept=".json" hidden data-chg="imp"></label><button class="btn danger" data-act="reset">Erase all data</button></div></div></div></div>
  <div class="card pad0" style="margin-top:16px"><div style="padding:16px 18px 0"><h3>Audit log</h3></div><div class="tablewrap"><table><tbody>${DB.audit.slice(0, 15).map(a => `<tr><td class="muted nowrap">${new Date(a.ts).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</td><td><b>${esc(a.who)}</b></td><td>${esc(a.msg)}</td></tr>`).join('')}</tbody></table></div></div>`;
};
document.addEventListener('submit', e => { if (e.target.id !== 'setf') return; e.preventDefault(); const d = Object.fromEntries(new FormData(e.target)); DB.company = d.company; ['CL', 'SL', 'EL', 'CO'].forEach(k => DB.settings.quota[k] = +d[k]); DB.settings.lateAfter = d.lateAfter; log('Updated settings'); save(); render(); toast('Settings saved'); });
ACT.exp = () => download('orbit-hr-backup.json', JSON.stringify(DB, null, 1), 'application/json');
CHG.imp = el => { const f = el.files[0]; if (!f) return; f.text().then(t => { try { const o = JSON.parse(t); if (!o.employees) throw 0; DB = o; save(); toast('Backup imported'); render(); } catch { toast('That file is not a valid backup', 'err'); } }); };
ACT.reset = () => confirmBox('Erase ALL employee data on this device and start again from the first-time setup? Export a backup first — this cannot be undone.', () => { DB = seed(); save(); logout(); });

/* ================= PALETTE ================= */
ACT.palette = () => {
  const items = [...PAGES.filter(p => !p[3] || p[3]()).map(p => ({ t: 'Go to ' + p[1], i: p[2], f: () => location.hash = '#/' + p[0] })),
  { t: 'Apply for leave', i: 'calendar', f: () => { location.hash = '#/leave'; setTimeout(ACT.leave_new, 50); } }, { t: 'Raise a helpdesk ticket', i: 'help', f: () => { location.hash = '#/helpdesk'; setTimeout(ACT.tk_new, 50); } }, { t: 'Toggle dark mode', i: 'moon', f: ACT.theme }, { t: 'Sign out', i: 'logout', f: logout },
  ...DB.employees.filter(e => e.status !== 'Exited').map(e => ({ t: e.name + ' — ' + e.title, i: 'users', f: () => location.hash = '#/employees/' + e.id }))];
  const m = document.createElement('div'); m.className = 'modal-bg'; m.innerHTML = `<div class="modal palette"><input id="pq" placeholder="Search people, pages, actions…" autocomplete="off"><ul id="pl"></ul></div>`; document.body.appendChild(m);
  let idx = 0, cur = items; const draw = () => { $('#pl', m).innerHTML = cur.slice(0, 40).map((x, i) => `<li class="${i === idx ? 'on' : ''}" data-i="${i}">${ic(x.i)}${esc(x.t)}</li>`).join('') || '<li class="muted">No results</li>'; };
  const run = i => { const x = cur[i]; if (x) { m.remove(); x.f(); } };
  m.addEventListener('mousedown', e => { if (e.target === m) m.remove(); }); m.addEventListener('click', e => { const li = e.target.closest('li[data-i]'); if (li) run(+li.dataset.i); });
  $('#pq', m).addEventListener('input', e => { const q = e.target.value.toLowerCase(); cur = items.filter(x => x.t.toLowerCase().includes(q)); idx = 0; draw(); });
  $('#pq', m).addEventListener('keydown', e => { if (e.key === 'ArrowDown') { idx = Math.min(idx + 1, cur.length - 1); draw(); e.preventDefault(); } if (e.key === 'ArrowUp') { idx = Math.max(0, idx - 1); draw(); e.preventDefault(); } if (e.key === 'Enter') run(idx); }); draw(); $('#pq', m).focus();
};

/* ================= ASSISTANT (rule-based, offline) ================= */
S.chat = { open: false, msgs: [{ b: 1, t: "Hi! I'm the Orbit assistant. Ask about your leave balance, holidays, who's out, payslips or policies." }] };
function answer(q) {
  q = q.toLowerCase(); const u = me(), T = TODAY();
  if (/balance|leaves? left|how many leaves?/.test(q)) return 'Your balances:\n' + ['CL', 'SL', 'EL', 'CO'].map(t => `• ${LEAVE_TYPES[t]}: ${leaveBalance(u.id, t).left} left`).join('\n');
  if (/who.*(leave|off|out)|on leave/.test(q)) { const o = activeEmps().filter(e => dayStatus(e.id, T).s === 'leave'); return o.length ? 'On leave today: ' + o.map(e => e.name).join(', ') : 'Nobody is on leave today.'; }
  if (/holiday/.test(q)) return 'Upcoming holidays:\n' + HOLIDAYS.filter(h => h[0] >= T).slice(0, 4).map(h => `• ${fmtDate(h[0])} — ${h[1]}`).join('\n');
  if (/birthday/.test(q)) { const b = activeEmps().map(e => [nextOcc(e.dob.slice(5)), e.name]).sort().slice(0, 3); return 'Next birthdays:\n' + b.map(x => `• ${x[1]} — ${fmtShort(x[0])}`).join('\n'); }
  if (/payslip|salary|pay\b|payroll/.test(q)) { const ym = monthsBack(6).find(m => isReleased(m, u.id)); if (!ym) return 'No payslips yet.'; return `Your latest payslip (${monthName(ym)}): net pay ${inr(payslip(u.id, ym).net)}. Open Payroll → My payslips to view it.`; }
  if (/headcount|how many (employees|people)/.test(q)) return `There are ${activeEmps().length} active people across ${new Set(activeEmps().map(e => e.dept)).size} departments.`;
  if (/apply.*leave|take.*leave|book.*leave/.test(q)) { setTimeout(() => { location.hash = '#/leave'; setTimeout(ACT.leave_new, 60); }, 300); return 'Opening the leave form for you…'; }
  if (/check.?in|punch in/.test(q)) { if (dayStatus(u.id, T).s !== 'notin') return "You've already been marked for today."; ACT.checkin(); return 'Done — you are checked in. ✅'; }
  if (/policy|policies/.test(q)) return 'Policies: ' + (DB.policies || []).filter(p => p.status === 'Published').map(p => p.title).join(', ') + '. Find them under Policies & docs.';
  if (/approval|pending/.test(q)) return `You have ${pendingCount()} item(s) waiting for approval.`;
  if (/manager|report to/.test(q)) return emp(u.mgr) ? `You report to ${emp(u.mgr).name}.` : "You're at the top of the org chart.";
  return "I can help with: leave balance, holidays, who's on leave, birthdays, payslips, headcount, policies, approvals — or say “apply for leave”.";
}
function drawChat() {
  const box = $('#chatbox'); if (!box) return; if (!S.chat.open) { box.innerHTML = ''; return; }
  box.innerHTML = `<div class="chat"><header>${ic('spark')}<b>Orbit Assistant</b><span class="small" style="opacity:.6">rule-based · offline</span><button class="icon-btn right" style="color:#fff" data-act="chat">${ic('x')}</button></header><div class="msgs" id="msgs">${S.chat.msgs.map(m => `<div class="m ${m.b ? 'bot' : 'me'}">${esc(m.t)}</div>`).join('')}</div><div class="sugg">${['Leave balance', 'Upcoming holidays', 'Who is on leave?', 'My payslip'].map(s => `<button data-act="ask" data-q="${s}">${s}</button>`).join('')}</div><form id="chatf"><input class="input" id="chq" placeholder="Ask anything…" autocomplete="off"><button class="btn primary">${ic('send')}</button></form></div>`;
  const ms = $('#msgs'); ms.scrollTop = ms.scrollHeight; $('#chatf').addEventListener('submit', e => { e.preventDefault(); const v = $('#chq').value.trim(); if (v) ask(v); }); $('#chq').focus();
}
function ask(v) { S.chat.msgs.push({ t: v }); S.chat.msgs.push({ b: 1, t: answer(v) }); drawChat(); }
ACT.chat = () => { S.chat.open = !S.chat.open; drawChat(); }; ACT.ask = el => ask(el.dataset.q);
const _render = render; render = function () { _render(); drawChat(); };


